//! material3's design tokens, as Compose's `androidx.compose.material3.tokens` (internal there): generated by
//! `cargo xtask material3-tokens` from material3 1.5.0-alpha17's sources, do not edit. The components read them as
//! they come (a token set unused until its component is here; Compose's names, `ShapeKeyTokens`' all
//! `Corner…`).

#![allow(dead_code, unused_imports, clippy::enum_variant_names)]

/// What the token files name.
mod prelude {
    pub(super) use super::*;
    pub(super) use kompoz_animation::CubicBezierEasing;
    pub(super) use kompoz_graphics::{
        CircleShape, Color, CornerSize, Dp, RectangleShape, RoundedCornerShape, TextUnit, TextUnitType,
    };
    pub(super) use kompoz_text::style::line_height_style::{Alignment, Mode, Trim};
    pub(super) use kompoz_text::{FontFamily, FontWeight, LineHeightStyle, TextStyle};
}

